// Writes src/asm/coff/winapi.ts: the names exported by msvcrt.dll, kernel32.dll and user32.dll,
// read from the export directories of the DLLs in C:\Windows\System32. The PE linker uses them to
// pick the DLL of every imported function and to reject names no DLL has. The generated file is
// committed; run this on Windows only to refresh it: node tools/gen-winapi.ts
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const DLLS = ['msvcrt.dll', 'kernel32.dll', 'user32.dll'];
const sys = join(process.env.SystemRoot ?? 'C:\\Windows', 'System32');

function exportNames(file: string): string[] {
  const b = readFileSync(file);
  const pe = b.readUInt32LE(0x3c), nsect = b.readUInt16LE(pe + 6), optSize = b.readUInt16LE(pe + 20);
  const opt = pe + 24;
  if (b.readUInt16LE(opt) !== 0x20b) throw new Error(`${file}: not a PE32+ image`);
  const expRva = b.readUInt32LE(opt + 112);
  const sects = Array.from({ length: nsect }, (_, i) => {
    const s = opt + optSize + i * 40;
    return { va: b.readUInt32LE(s + 12), vsize: b.readUInt32LE(s + 8), raw: b.readUInt32LE(s + 20) };
  });
  const off = (rva: number) => {
    const s = sects.find((x) => rva >= x.va && rva < x.va + x.vsize)!;
    return rva - s.va + s.raw;
  };
  const dir = off(expRva), n = b.readUInt32LE(dir + 24), names = off(b.readUInt32LE(dir + 32));
  const out: string[] = [];
  for (let i = 0; i < n; i++) {
    const p = off(b.readUInt32LE(names + 4 * i));
    out.push(b.toString('latin1', p, b.indexOf(0, p)));
  }
  return out;
}

// front coding: sorted names, each written as (length of the prefix shared with the previous name) + rest
const DIGITS = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
function pack(names: string[]): string {
  const sorted = [...new Set(names)].sort();
  let prev = '';
  return sorted.map((n) => {
    let k = 0;
    while (k < Math.min(prev.length, n.length, DIGITS.length - 1) && prev[k] === n[k]) k++;
    prev = n;
    return DIGITS[k] + n.slice(k);
  }).join(',');
}

const lines = [
  '// Generated by tools/gen-winapi.ts from the export directories of the Windows 11 system DLLs. Do not edit.',
  '// Names exported by the DLLs the PE linker imports from, front-coded: every entry starts with a digit',
  '// (0-9a-zA-Z) giving how many leading characters it shares with the previous name.',
  `const DIGITS = '${DIGITS}';`,
  'const PACKED: Record<string, string> = {',
];
for (const d of DLLS) {
  const names = exportNames(join(sys, d));
  lines.push(`  '${d}': '${pack(names)}',`);
  console.log(`${d}: ${names.length} names`);
}
lines.push('};', '', `/** DLLs in the order the linker searches them */
export const SYSTEM_DLLS = Object.keys(PACKED);

const cache = new Map<string, Set<string>>();
/** The names a system DLL exports. */
export function systemExports(dll: string): Set<string> {
  let set = cache.get(dll);
  if (set) return set;
  set = new Set();
  let prev = '';
  for (const e of (PACKED[dll] ?? '').split(',')) {
    if (!e) continue;
    prev = prev.slice(0, DIGITS.indexOf(e[0])) + e.slice(1);
    set.add(prev);
  }
  cache.set(dll, set);
  return set;
}
`);
writeFileSync('src/asm/coff/winapi.ts', lines.join('\n'));
console.log('wrote src/asm/coff/winapi.ts');
